export const allPresets=Object.entries(presetLibrary).flatMap(([genre,items])=>items.map(p=>({...p,genre})));
export function getPreset(id){return allPresets.find(p=>p.id===id);}
export function arrangePreset(p){
 const sequence=Array.from({length:64},(_,i)=>p.notes[i%16]?p.notes[i%16]+p.transpose[Math.floor(i/16)]:0);
 const drums=p.drums.map(row=>Array.from({length:64},(_,i)=>row[i%16]));
 for(const [track,step,value]of p.fills||[])drums[track][step]=value;
 // Melody responses in bars 2 and 4; the original phrase is never mutated.
 if(p.genre!=='funk'){if(sequence[30])sequence[30]=Math.min(84,sequence[30]+7);if(sequence[63])sequence[63]=Math.max(24,sequence[63]-2);}
 return {sequence,drums};
}
